def main():
    print(f"Validating MRCP topics ({len(MRCP_TOPICS)})...")
    for i, t in enumerate(MRCP_TOPICS):
        title, subj, sys_name, focus, guide, url = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in MRCP #{i+1}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in MRCP #{i+1}"
        assert len(title) > 20, f"Title too short in MRCP #{i+1}"
        assert url.startswith("https://"), f"Bad URL in MRCP #{i+1}"

    print(f"Validating FCPS topics ({len(FCPS_TOPICS)})...")
    for i, t in enumerate(FCPS_TOPICS):
        title, subj, sys_name, focus, guide, url = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in FCPS #{i+1}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in FCPS #{i+1}"
        assert len(title) > 20, f"Title too short in FCPS #{i+1}"
        assert url.startswith("https://"), f"Bad URL in FCPS #{i+1}"

    print(f"Validating NLE topics ({len(NLE_TOPICS)})...")
    for i, t in enumerate(NLE_TOPICS):
        title, subj, sys_name, focus, guide, url = t
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in NLE #{i+1}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in NLE #{i+1}"
        assert len(title) > 20, f"Title too short in NLE #{i+1}"
        assert url.startswith("https://"), f"Bad URL in NLE #{i+1}"

    print("All 300 topics in Part B passed validation!")

    out_path = "scripts/mega73_topics_b.py"
    with open(out_path, "w", encoding="utf-8") as f:
        f.write("# Auto-generated Mega-Batch 73 Part B topics\n")
        f.write(f"MRCP_TOPICS = {repr(MRCP_TOPICS)}\n\n")
        f.write(f"FCPS_TOPICS = {repr(FCPS_TOPICS)}\n\n")
        f.write(f"NLE_TOPICS = {repr(NLE_TOPICS)}\n")
    print(f"Saved topics to {out_path}")

if __name__ == "__main__":
    main()
